#!/usr/bin/env bash
# Production bootstrap for MAMOGRAF on VM 10.10.0.75 (behind edge TLS proxy).
# Run from the project root:  bash deploy_prod.sh
set -euo pipefail

cd "$(dirname "$0")"
COMPOSE="docker compose -f docker-compose.prod.yml"

# --- 1) .env with a generated JWT secret (only if missing) --------------------
if [ ! -f .env ]; then
  echo "[deploy] .env topilmadi — yaratamiz (JWT_SECRET generatsiya)..."
  cat > .env <<EOF
# Auto-generated by deploy_prod.sh — DO NOT commit.
JWT_SECRET=$(openssl rand -base64 48)
AUTO_DEIDENTIFY=1
LOCAL_DICOM_HOST_PATH=./dicom_data
EOF
  chmod 600 .env
  echo "[deploy] .env yaratildi."
else
  echo "[deploy] .env mavjud — saqlanib qoldi."
fi

# --- 2) read-only DICOM mount point (empty is fine) ---------------------------
mkdir -p dicom_data

# --- 3) Build + start ---------------------------------------------------------
echo "[deploy] Image qurilmoqda (ultralytics/torch tufayli uzoq davom etishi mumkin)..."
$COMPOSE build

echo "[deploy] App ishga tushmoqda..."
$COMPOSE up -d

echo
echo "[deploy] ===== HOLAT ====="
$COMPOSE ps
echo
echo "Keyingi qadam — birinchi admin yarating (parol so'raydi):"
echo "  $COMPOSE exec app python -m app.manage_users create admin --role admin"
echo
echo "Lokal tekshiruv:  curl -s http://localhost:8081/ | head"
echo "Edge proxy:       aiscan.airi.uz:443  ->  10.10.0.75:8081"
